join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P119', 'P137', 'P227', 'P162', 'P179', 'P039', 'P113', 'P130', 'P041', 'P049', 'P079', 'P129', 'P141', 'P175', 'P176', 'P221', 'P055', 'P139', 'P181', 'P183', 'P184', 'P209', 'P212', 'P214', 'P215')) <> 25 then
    raise exception 'a character of the seventh batch has no kit';
  end if;
end $$;
